steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        teams {
          nodes {
            id
            name
            key
            cycles(orderBy: startDate) {
              nodes {
                id
                name
                startDate
                targetDate
                completedAt
              }
            }
          }
        }
      }
    "
  }'
